(()=>{
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9\s]/g,' ').replace(/\s+/g,' ').trim();
const all=()=>window.BoraCourses;
const record=(u,c,l)=>{u.courseProgress??={};return u.courseProgress[c.id+'/'+l.id]??={stage:0,answers:{},attempts:0,correct:0,note:'',done:false}};
const cite=c=>`<p class="small course-source">Адаптация на русском с сокращениями и новыми упражнениями по <a href="${c.url}" target="_blank" rel="noopener noreferrer">${esc(c.source)}</a>. <a href="${c.licenseUrl}" target="_blank" rel="noopener noreferrer">${c.license}</a>. Авторы исходника адаптацию не проверяли.</p>`;
const summary=u=>all().map(c=>({course:c,done:c.lessons.filter(l=>u.courseProgress?.[c.id+'/'+l.id]?.done).length,total:c.lessons.length}));
function page(u){const parts=location.hash.slice(1).split('/'),c=all().find(c=>c.id===parts[1]);
if(!c)return `<div class="eyebrow">Коротко · понятно · с практикой</div><h1>Учиться, чтобы общаться.</h1><p>Один урок — примерно 5–10 минут: понятная идея, примеры и маленький разговор. Начни с первого или выбери нужную тему.</p><div class="course-grid">${summary(u).map(({course:c,done,total})=>`<article class="panel"><span class="pill">${c.language==='pt-BR'?'🇧🇷 Бразилия':'Английский'} · начальный курс</span><h2>${esc(c.title)}</h2><p>${esc(c.description)}</p><progress value="${done}" max="${total}" aria-label="Пройдено уроков"></progress><p class="small">${done} из ${total} уроков завершено</p><a class="btn" href="#courses/${c.id}">Открыть программу →</a></article>`).join('')}</div><div class="notice">Португальский курс даёт базу для бытового общения. Подготовка к Celpe-Bras потребует отдельной программы с аудированием, письмом и устной практикой.</div>`;
const l=c.lessons.find(l=>l.id===parts[2]);if(!l){const s=summary(u).find(x=>x.course===c),next=c.lessons.find(l=>!u.courseProgress?.[c.id+'/'+l.id]?.done)||c.lessons[0];return `<a class="back" href="#courses">← Все программы</a><div class="panel"><span class="pill">${c.language==='pt-BR'?'🇧🇷 Português do Brasil':'English'} · с нуля</span><h1>${esc(c.title)}</h1><p>${esc(c.description)}</p><progress value="${s.done}" max="${s.total}" aria-label="Прогресс курса"></progress><p>${s.done} из ${s.total} уроков</p><a class="btn yellow" href="#courses/${c.id}/${next.id}">Продолжить обучение →</a></div><div class="lesson-list">${c.lessons.map((l,i)=>{const r=u.courseProgress?.[c.id+'/'+l.id];return `<a class="card lesson-link" href="#courses/${c.id}/${l.id}"><span class="lesson-number">${r?.done?'✓':String(i+1).padStart(2,'0')}</span><div><h3>${esc(l.title)}</h3><p>${esc(l.scene)}</p><span class="small">${r?.done?'Пройдено · можно повторить':r?.stage?'Начато · продолжить':'5–10 минут · '+esc(l.topic)}</span></div><span>→</span></a>`}).join('')}</div>${cite(c)}`}
const r=record(u,c,l),st=r.stage;let body='';
if(st===0)body=`<div class="notice">Твоя ситуация: ${esc(l.scene)}</div><h2>Одна простая идея</h2><p class="course-explain">${esc(l.idea)}</p>${l.examples.map(([pt,ru])=>`<div class="example"><strong lang="${c.language}">${esc(pt)}</strong><p>${esc(ru)}</p></div>`).join('')}<button class="btn" id="course-next">Попробовать →</button>`;
else if(st===1||st===2){const q=l.quiz[st-1],a=r.answers[st];body=`<h2>${esc(q[0])}</h2><p class="small">Выбери ответ. Если ошибёшься, разберём вместе.</p><div class="options">${q[1].map((o,i)=>`<button class="option" data-course-choice="${i}" ${a?.passed?'disabled':''}>${esc(o)}</button>`).join('')}</div><div id="course-feedback" role="status" aria-live="polite">${a?`<div class="feedback ${a.passed?'':'bad'}">${a.passed?'Получилось!':'Попробуй ещё раз.'} ${esc(q[3])}</div>`:''}</div><button class="btn" id="course-next" ${a?.passed?'':'disabled'}>Дальше →</button>`}
else if(st===3){const a=r.answers[3];body=`<h2>Теперь своими руками</h2><p>${esc(l.write[0])}</p><form id="course-write"><label>Твой ответ<input id="course-input" maxlength="200" autocomplete="off" value="${esc(a?.draft||'')}" ${a?.passed?'disabled':''} required></label><button class="btn" ${a?.passed?'disabled':''}>Проверить ответ</button></form><p class="small">Регистр и ударения не влияют на зачёт. После ответа покажем правильное написание.</p><div id="course-feedback" role="status" aria-live="polite">${a?.passed?`<div class="feedback">Получилось! ${esc(l.write[2])}</div>`:''}</div><details><summary>Нужна подсказка?</summary><p>${esc(l.write[2])}</p></details><button class="btn" id="course-next" ${a?.passed?'':'disabled'}>К мини-разговору →</button>`}
else body=`<h2>Используй в жизни</h2><div class="example"><p>${esc(l.mission)}</p></div><label for="course-note">Твоя фраза или мини-диалог</label><textarea id="course-note" maxlength="1500" placeholder="Сохрани здесь свою фразу…">${esc(r.note)}</textarea><p class="small">Заметка сохраняется без автоматической оценки. Помощник может её разобрать.</p><div class="row"><button class="btn alt" id="course-ask">Разобрать с помощником</button><button class="btn" id="course-finish" ${r.note.trim()?'':'disabled'}>${r.done?'Сохранить и вернуться':'Я попробовал — завершить урок ✓'}</button></div>`;
return `<div class="narrow"><a class="back" href="#courses/${c.id}">← Программа курса</a><div class="panel"><div class="eyebrow">Урок ${c.lessons.indexOf(l)+1} из ${c.lessons.length} · ${['Разберёмся','Выберем фразу','Проверим логику','Напишем сами','Мини-разговор'][st]}</div><h1>${esc(l.title)}</h1><progress value="${st+1}" max="5" aria-label="Шаг ${st+1} из 5"></progress><p class="small">Шаг ${st+1} из 5 ${r.done?'· урок уже пройден':''}</p>${body}${st?'<button class="btn alt course-back" id="course-back">← Предыдущий шаг</button>':''}</div>${cite(c)}</div>`;
}
function bind(u,save,render){if(!location.hash.startsWith('#courses/'))return;const p=location.hash.slice(1).split('/'),c=all().find(c=>c.id===p[1]),l=c?.lessons.find(l=>l.id===p[2]);if(!l)return;const r=record(u,c,l),$=s=>document.querySelector(s),paint=()=>{save();render()};
if($('#course-next'))$('#course-next').onclick=()=>{if(r.stage>0&&!r.answers[r.stage]?.passed)return;r.stage=Math.min(4,r.stage+1);paint();window.scrollTo(0,0)};
if($('#course-back'))$('#course-back').onclick=()=>{r.stage=Math.max(0,r.stage-1);paint()};
document.querySelectorAll('[data-course-choice]').forEach(b=>b.onclick=()=>{const st=r.stage;if(r.answers[st]?.passed)return;const passed=Number(b.dataset.courseChoice)===l.quiz[st-1][2];r.attempts++;if(passed)r.correct++;r.answers[st]={passed};paint()});
if($('#course-write'))$('#course-write').onsubmit=e=>{e.preventDefault();if(r.answers[3]?.passed)return;const draft=$('#course-input').value,passed=l.write[1].some(v=>norm(v)===norm(draft));r.attempts++;if(passed)r.correct++;r.answers[3]={passed,draft};save();$('#course-feedback').innerHTML=`<div class="feedback ${passed?'':'bad'}">${passed?'Получилось! '+esc(l.write[2]):'Пока не совпало. Сверь порядок слов. Можно открыть подсказку.'}</div>`;if(passed){$('#course-next').disabled=false;$('#course-input').disabled=true;$('#course-write').querySelector('button').disabled=true}};
if($('#course-input'))$('#course-input').oninput=e=>{r.answers[3]={...r.answers[3],draft:e.target.value};save()};
if($('#course-note'))$('#course-note').oninput=e=>{r.note=e.target.value;save();$('#course-finish').disabled=!r.note.trim()};
if($('#course-ask'))$('#course-ask').onclick=()=>{u.tutorDraft=`Изучаю ${c.language==='pt-BR'?'бразильский португальский':'английский'}. Тема: ${l.title}. Задание: ${l.mission}\nМой ответ: ${r.note}\nОбъясни по-русски, что получилось и что исправить.`;u.tutorLanguage=c.language;save();location.hash='assistant'};
if($('#course-finish'))$('#course-finish').onclick=()=>{if(!r.note.trim()||![1,2,3].every(i=>r.answers[i]?.passed))return;r.done=true;r.finishedAt=new Date().toISOString();save();location.hash='courses/'+c.id};
}
window.BoraLearning={page,bind,summary,norm};
})();
